#include <sqlite3.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include "bonfyre.h"
#include "../../../lib/libbonfyre/include/bf_command_lookup.h"

static const char*arg(int c,char**v,const char*n){for(int i=2;i+1<c;i++)if(!strcmp(v[i],n))return v[i+1];return NULL;}
static char*slurp(const char*p,size_t*n){FILE*f=fopen(p,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static void atom(const char*in,char*out,size_t cap){size_t j=0;for(size_t i=0;in&&in[i]&&j+1<cap;i++){unsigned char c=(unsigned char)in[i];if(c>='A'&&c<='Z')c=(unsigned char)(c+32);if((c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_')out[j++]=(char)c;else if(j&&out[j-1]!='-')out[j++]='-';}while(j&&out[j-1]=='-')j--;out[j]=0;}
static int mkdir_ok(const char*p){return p&&*p&&(mkdir(p,0750)==0||errno==EEXIST);}
static int emit(const char*dir,const char*source,const char*old,const char*now,const char*old_decision,const char*new_decision,const char*old_digest,const char*new_digest){char a[256],path[1400],tmp[1440];FILE*f=NULL;atom(source,a,sizeof(a));if(!a[0]||!mkdir_ok(dir)||snprintf(path,sizeof(path),"%s/resource-weather-%s-%s-%s-%s.json",dir,a,old&&*old?old:"absent",now&&*now?now:"absent",new_digest)>=(int)sizeof(path))return 0;if(!access(path,F_OK))return 1;if(snprintf(tmp,sizeof(tmp),"%s.tmp",path)>=(int)sizeof(tmp)||(f=fopen(tmp,"w"))==NULL)return 0;fprintf(f,"{\"schema\":\"bonfyre-fact-delta.v1\",\"delta_id\":\"resource-weather:%s:%s:%s\",\"writes\":[\"ResourceWeather:%s\"],\"source\":\"%s\",\"from_tier\":\"%s\",\"to_tier\":\"%s\",\"from_decision\":\"%s\",\"to_decision\":\"%s\",\"previous_snapshot_digest\":\"%s\",\"snapshot_digest\":\"%s\",\"truth\":\"source_standing_changed_only\"}\n",a,old_digest,new_digest,source,source,old&&*old?old:"absent",now&&*now?now:"absent",old_decision&&*old_decision?old_decision:"absent",new_decision&&*new_decision?new_decision:"absent",old_digest,new_digest);if(fflush(f)||fsync(fileno(f))||fclose(f)||rename(tmp,path)){if(f)fclose(f);unlink(tmp);return 0;}return 1;}
static int source_state(sqlite3*d,const char*json,const char*source,char*tier,size_t tier_cap,char*decision,size_t decision_cap){sqlite3_stmt*q=NULL;int ok=0;tier[0]=0;decision[0]=0;if(sqlite3_prepare_v2(d,"SELECT json_extract(value,'$.tier'),COALESCE(json_extract(value,'$.decision'),'') FROM json_each(?1,'$.sources') WHERE json_extract(value,'$.source')=?2 LIMIT 1",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,json,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,source,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)){snprintf(tier,tier_cap,"%s",(const char*)sqlite3_column_text(q,0));if(sqlite3_column_text(q,1))snprintf(decision,decision_cap,"%s",(const char*)sqlite3_column_text(q,1));ok=1;}sqlite3_finalize(q);return ok;}
static int weather_schema(sqlite3*d,const char*json,size_t n){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,'$.schema')",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,json,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)&&!strcmp((const char*)sqlite3_column_text(q,0),"bonfyre-resource-weather.v1"))ok=1;sqlite3_finalize(q);return ok;}
int main(int argc,char**argv){const char*oldp=arg(argc,argv,"--old"),*newp=arg(argc,argv,"--new"),*out=arg(argc,argv,"--out");char*old=NULL,*now=NULL,old_digest[65]={0},new_digest[65]={0};size_t on=0,nn=0;sqlite3*d=NULL;sqlite3_stmt*set=NULL;int changed=0,unchanged=0,added=0,removed=0,ok=0;enum{RD_DIFF};static const BfCommandEntry delta_commands[]={{"diff",RD_DIFF,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(delta_commands,sizeof(delta_commands)/sizeof(delta_commands[0]),argv[1]);if(argc<2||!command||command->id!=RD_DIFF||!oldp||!newp||!out)return 2;if(!(old=slurp(oldp,&on))||!(now=slurp(newp,&nn))||sqlite3_open(":memory:",&d)!=SQLITE_OK||!weather_schema(d,old,on)||!weather_schema(d,now,nn))goto done;bf_sha256_hex((const uint8_t*)old,on,old_digest);bf_sha256_hex((const uint8_t*)now,nn,new_digest);if(sqlite3_prepare_v2(d,"WITH s(x) AS (SELECT json_extract(value,'$.source') FROM json_each(?1,'$.sources') UNION SELECT json_extract(value,'$.source') FROM json_each(?2,'$.sources')) SELECT x FROM s WHERE x IS NOT NULL ORDER BY x",-1,&set,NULL)!=SQLITE_OK)goto done;sqlite3_bind_text(set,1,old,(int)on,SQLITE_TRANSIENT);sqlite3_bind_text(set,2,now,(int)nn,SQLITE_TRANSIENT);while(sqlite3_step(set)==SQLITE_ROW){const char*s=(const char*)sqlite3_column_text(set,0);char a[32]={0},b[32]={0},ad[128]={0},bd[128]={0};int ao=source_state(d,old,s,a,sizeof(a),ad,sizeof(ad)),bo=source_state(d,now,s,b,sizeof(b),bd,sizeof(b));if(ao&&bo&&!strcmp(a,b)&&!strcmp(ad,bd)){unchanged++;continue;}if(!emit(out,s,ao?a:"absent",bo?b:"absent",ao?ad:"absent",bo?bd:"absent",old_digest,new_digest))goto done;changed++;if(!ao)added++;if(!bo)removed++;}printf("{\"changed\":%d,\"unchanged\":%d,\"added\":%d,\"removed\":%d,\"previous_snapshot_digest\":\"%s\",\"snapshot_digest\":\"%s\",\"truth\":\"resource_weather_fact_delta_only\"}\n",changed,unchanged,added,removed,old_digest,new_digest);ok=1;
done:sqlite3_finalize(set);if(d)sqlite3_close(d);free(old);free(now);return ok?0:1;}
